"""Note 106 : page de test SY separee, principal 1.78 conserve."""
import argparse,pathlib,re,shutil,json,tempfile
ROOT=pathlib.Path(__file__).resolve().parents[1];STAMP='2026-10-16-sy-load-test-2'
def main():
 p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');a=p.parse_args();expected=ROOT/'docs/flasher-sy-load-test';tmp=tempfile.TemporaryDirectory(dir=ROOT/'build') if a.check else None;out=pathlib.Path(tmp.name) if tmp else expected;out.mkdir(exist_ok=True)
 for src in (ROOT/'docs/flasher').iterdir():
  if src.is_file() and src.suffix!='.wav':shutil.copyfile(src,out/src.name)
 s=(out/'index.html').read_text(encoding='utf-8');s=re.sub(r'(?<=\?v=)[\w.-]+',STAMP,s);s=re.sub(r"window.MC_BUILD='[^']+'",f"window.MC_BUILD='{STAMP}'",s)
 s=s.replace('<main class="wrap fl">','<main class="wrap fl"><p class="alert"><span data-l="en"><strong>Experimental SY load test 2.</strong> Exact shared repeat optimization and optional Lite Syn Swarm (3 oscillators instead of 7). Lite changes the sound and may be quieter; gain is not boosted. First try Repeat / SY load optimization with Lite Syn Swarm off. Audio load diagnostic shows average / peak CPU after releasing TRACK + RETRIG. Main unchanged. Hardware verification pending.</span><span data-l="fr"><strong>Test charge SY experimental 2.</strong> Repeat partage optimise et Syn Swarm leger facultatif (3 oscillateurs au lieu de 7). Son lite modifie, parfois moins fort ; gain non augmente. Essayer d abord Optimisation repeat / SY avec Swarm leger decoche. Diagnostic CPU moyenne / pic au relachement TRACK + RETRIG. Principal inchange. Verification materielle attendue.</span></p>')
 s=s.replace('../assets/release.js?','sy-load-release.js?').replace('</body>',f'<script src="swarm-lite-data.js?v={STAMP}"></script><script src="sy-load.js?v={STAMP}"></script></body>');(out/'index.html').write_text(s,encoding='utf-8')
 (out/'swarm-lite-data.js').write_text((ROOT/'build/swarm-lite/swarm-lite-data.js').read_text()+ 'window.MCSyMeter='+json.dumps(json.loads((ROOT/'build/swarm-lite/beat-meter-data.json').read_text()),separators=(',',':'))+';\n');shutil.copyfile(ROOT/'tools/machines/syntakt_load/lite.js',out/'sy-load.js')
 (out/'sy-load-release.js').write_text('window.MC_RELEASES='+json.dumps([dict(version='1.79-sy-load-preview.2',date='2026-10-16',changes=[dict(en='Exact steady-repeat and history-copy optimizations for all voice types, plus optional three-oscillator Syn Swarm. Lite changes timbre and level. Compare six-track playback with repeat and filter. Main 1.78 unchanged; hardware test pending.',fr='Repeat etabli et historique optimises pour toutes les voix, plus Syn Swarm facultatif a trois oscillateurs. Timbre/niveau lite modifies. Comparer six pistes avec repeat et filtre. Principal 1.78 inchange ; test machine attendu.')])])+';\n')
 (out/'TEST-NOTES.md').write_text('Experimental SY load test. First enable Audio load diagnostic with your original SY voices. Hold TRACK + RETRIG while the clicks occur, then release: CPU average / peak appears. Record both values. Next enable Repeat / SY load optimization while leaving Lite off to compare the shared exact fast path. Finally enable optional Lite Syn Swarm for a three-oscillator comparison. Its tone and level can change. Toy/Bits generators are unchanged; the shared repeat optimization frees headroom for them too. Main unchanged. Test multiple SY voices, repeat with/without a division pad, cutoff, stop, project changes and release fades. Hardware verification pending.\n\nTest charge SY experimental. Activer d abord Diagnostic charge audio avec les voix SY originales. Maintenir TRACK + RETRIG pendant les clicks puis relacher : CPU moyenne / pic. Noter les deux valeurs. Activer ensuite Optimisation repeat / SY en laissant Lite decoche pour comparer le chemin partage exact. Puis activer facultativement Syn Swarm leger pour comparer trois oscillateurs. Timbre/niveau peuvent changer. Generateurs Toy/Bits inchanges ; repeat partage allege pour eux aussi. Principal inchange. Tester plusieurs SY, repeat avec/sans pad, coupure, stop, changement projet et fondus. Verification materielle attendue.\n',encoding='utf-8')
 for src in out.iterdir():
  if src.suffix in ('.js','.html','.css','.md','.txt'):src.write_text('\n'.join(line.rstrip() for line in src.read_text(encoding='utf-8').splitlines()).rstrip()+'\n',encoding='utf-8')
 if a.check:
  for src in out.iterdir():assert src.read_bytes().replace(b'\r\n',b'\n')==(expected/src.name).read_bytes().replace(b'\r\n',b'\n'),src.name
 print('PASS page SY separee')
if __name__=='__main__':main()
